"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { ICONS, projects } from "../lib/data";

export default function HomeClient() {
  const router = useRouter();
  // Starts hidden so there's no flash of the homepage before the redirect
  // check below resolves.
  const [ready, setReady] = useState(false);

  useEffect(() => {
    if (sessionStorage.getItem("introPlayed")) {
      setReady(true);
    } else {
      router.replace("/intro");
    }
  }, [router]);

  if (!ready) return null;

  return (
    <main className="mx-auto flex h-full max-w-4xl flex-col justify-center gap-6 overflow-hidden px-6 py-24">
      {Object.values(projects).map((project) => (
        <Link
          key={project.id}
          href={`/${project.id}`}
          className="group flex items-center gap-5 rounded-2xl p-6 transition-colors"
          style={{ backgroundColor: project.color }}
        >
          <span
            className="flex h-12 w-12 shrink-0 items-center justify-center rounded-full"
            style={{ color: project.accent }}
          >
            {ICONS[project.id]}
          </span>
          <span className="flex flex-col">
            <span
              className="text-xs uppercase tracking-widest"
              style={{ color: project.accent }}
            >
              {project.tag}
            </span>
            <span className="text-2xl font-semibold text-white">
              {project.title}
            </span>
            <span className="text-sm text-white/70">{project.short}</span>
          </span>
        </Link>
      ))}
    </main>
  );
}